def strip_tags(html):
    return re.sub(r'<[^>]*>', '', html)

def matrix_product(a, b):
    return [[sum(a[i][k] * b[k][j] for k in range(len(b))) for j in range(len(b[0]))]
            for i in range(len(a))]

import math

def sphere_volume(r):
    return round(4 / 3 * math.pi * r ** 3, 2)

def consecutive_runs(nums):
    runs = []
    for x in nums:
        if runs and x == runs[-1][-1] + 1:
            runs[-1].append(x)
        else:
            runs.append([x])
    return runs

import re

def numbers_in_text(text):
    return [int(m) for m in re.findall(r'\d+', text)]

def english_join(words):
    if len(words) <= 1:
        return ''.join(words)
    return ', '.join(words[:-1]) + ' and ' + words[-1]

def border_sum(matrix):
    rows, cols = len(matrix), len(matrix[0])
    return sum(matrix[r][c] for r in range(rows) for c in range(cols)
               if r in (0, rows - 1) or c in (0, cols - 1))

def max_with_position(matrix):
    best = (matrix[0][0], 0, 0)
    for r, row in enumerate(matrix):
        for c, x in enumerate(row):
            if x > best[0]:
                best = (x, r, c)
    return best

def is_perfect_cube(n):
    k = round(abs(n) ** (1 / 3))
    return any((s * c) ** 3 == n for c in (k - 1, k, k + 1) for s in (1, -1))

def brackets_match_all(text):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack
